var (
	LootTablesOnce sync.Once
	LootTablesVal  map[string]map[string]any
)

// LootTables returns the vanilla loot table registry, keyed by table
// path inside data/minecraft/loot_table ("blocks/stone",
// "entities/pig", "chests/simple_dungeon", ...). Tables are decoded
// from the embedded data pack on first use; the raw JSON shape is what
// the interpreter in internal/loot walks.
func LootTables() map[string]map[string]any {
	LootTablesOnce.Do(func() {
		LootTablesVal = decodeBlob(lootBlob)
	})
	return LootTablesVal
}
